package com.cognitivekernel.androidfit;
import android.app.*;import android.os.Bundle;import android.view.View;import android.widget.*;import android.content.*;import android.database.Cursor;import android.hardware.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
public class MainActivity extends Activity implements SensorEventListener {
 WorkoutDb db; TextView status; SensorManager sm; Sensor step; float base=-1; static final int EXPORT=10;
 public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);db=new WorkoutDb(this);status=findViewById(R.id.statusText);findViewById(R.id.managePlansButton).setOnClickListener(v->manage());findViewById(R.id.logWorkoutButton).setOnClickListener(v->log());findViewById(R.id.stepsButton).setOnClickListener(v->steps());findViewById(R.id.exportButton).setOnClickListener(v->export());findViewById(R.id.reportButton).setOnClickListener(v->report());sm=(SensorManager)getSystemService(SENSOR_SERVICE);step=sm.getDefaultSensor(Sensor.TYPE_STEP_COUNTER);}
 EditText edit(String h,String val){EditText e=new EditText(this);e.setHint(h);if(val!=null)e.setText(val);e.setSingleLine(true);return e;} void msg(String t,String m){new AlertDialog.Builder(this).setTitle(t).setMessage(m).setPositiveButton("OK",null).show();}
 void manage(){List<String[]> p=db.plans();String[] a=new String[p.size()+1];a[0]="+ برنامه جدید";for(int i=0;i<p.size();i++)a[i+1]=p.get(i)[1];new AlertDialog.Builder(this).setTitle("برنامه‌ها").setItems(a,(d,w)->{if(w==0){EditText n=edit("نام برنامه",null);new AlertDialog.Builder(this).setView(n).setPositiveButton("ذخیره",(x,y)->{String s=n.getText().toString().trim();if(!s.isEmpty())showPlan(new String[]{""+db.addPlan(s),s});}).setNegativeButton("لغو",null).show();}else showPlan(p.get(w-1));}).setNegativeButton("بستن",null).show();}
 void showPlan(String[] p){List<String[]> e=db.exercises(Long.parseLong(p[0]));String[] a=new String[e.size()+2];a[0]="+ افزودن حرکت";a[1]="حذف برنامه";for(int i=0;i<e.size();i++)a[i+2]=e.get(i)[1]+" - "+e.get(i)[2]+"x"+e.get(i)[3];new AlertDialog.Builder(this).setTitle(p[1]).setItems(a,(d,w)->{if(w==0)addEx(p);else if(w==1){new AlertDialog.Builder(this).setMessage("برنامه و تمام حرکات آن حذف شود؟").setPositiveButton("حذف",(x,y)->{db.deletePlan(Long.parseLong(p[0]));manage();}).setNegativeButton("لغو",null).show();}else editEx(e.get(w-2));}).setPositiveButton("پایان",null).show();}
 void addEx(String[] p){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);EditText n=edit("نام حرکت",null),s=edit("ست","3"),r=edit("تکرار","10");s.setInputType(2);r.setInputType(2);l.addView(n);l.addView(s);l.addView(r);new AlertDialog.Builder(this).setTitle("افزودن حرکت").setView(l).setPositiveButton("ذخیره",(d,w)->{try{if(n.getText().toString().trim().isEmpty()||Integer.parseInt(s.getText().toString())<1||Integer.parseInt(r.getText().toString())<1)throw new Exception();db.addExercise(Long.parseLong(p[0]),n.getText().toString().trim(),Integer.parseInt(s.getText().toString()),Integer.parseInt(r.getText().toString()));showPlan(p);}catch(Exception e){msg("خطا","مقادیر معتبر وارد کنید.");}}).setNegativeButton("لغو",null).show();}
 void editEx(String[] e){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);EditText n=edit("نام حرکت",e[1]),s=edit("ست",e[2]),r=edit("تکرار",e[3]);s.setInputType(2);r.setInputType(2);l.addView(n);l.addView(s);l.addView(r);new AlertDialog.Builder(this).setTitle("ویرایش").setView(l).setPositiveButton("ذخیره",(d,w)->{try{String name=n.getText().toString().trim();int sets=Integer.parseInt(s.getText().toString()),reps=Integer.parseInt(r.getText().toString());if(name.isEmpty()||sets<1||reps<1)throw new Exception();db.updateExercise(Long.parseLong(e[0]),name,sets,reps);msg("ذخیره","انجام شد");}catch(Exception x){msg("خطا","مقادیر معتبر نیستند");}}).setNeutralButton("حذف",(d,w)->db.deleteExercise(Long.parseLong(e[0]))).setNegativeButton("لغو",null).show();}
 void log(){List<String[]> p=db.plans();if(p.isEmpty()){msg("برنامه‌ای نیست","ابتدا برنامه بسازید");return;}String[] pn=new String[p.size()];for(int i=0;i<p.size();i++)pn[i]=p.get(i)[1];LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);Calendar c=Calendar.getInstance();final String[] date={JalaliDate.fromGregorian(c.get(Calendar.YEAR),c.get(Calendar.MONTH)+1,c.get(Calendar.DAY_OF_MONTH))};TextView dt=new TextView(this);dt.setText("تاریخ شمسی: "+date[0]);l.addView(dt);dt.setOnClickListener(v->PersianDatePicker.show(this,date[0],selected->{date[0]=selected;dt.setText("تاریخ شمسی: "+date[0]);}));Spinner ps=new Spinner(this);ps.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,pn));l.addView(ps);Spinner es=new Spinner(this);l.addView(es);TextView spec=new TextView(this);l.addView(spec);EditText kg=edit("وزن کیلوگرم","0");kg.setInputType(8194);l.addView(kg);Runnable load=()->{int i=ps.getSelectedItemPosition();if(i<0)return;List<String[]> ex=db.exercises(Long.parseLong(p.get(i)[0]));String[] ns=new String[ex.size()];for(int j=0;j<ex.size();j++)ns[j]=ex.get(j)[1];es.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,ns));if(!ex.isEmpty())spec.setText(ex.get(0)[2]+" ست × "+ex.get(0)[3]+" تکرار");};ps.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> a){}public void onItemSelected(AdapterView<?> a,View v,int i,long id){load.run();}});es.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> a){}public void onItemSelected(AdapterView<?> a,View v,int i,long id){int j=ps.getSelectedItemPosition();if(j>=0){List<String[]> ex=db.exercises(Long.parseLong(p.get(j)[0]));if(i>=0&&i<ex.size())spec.setText(ex.get(i)[2]+" ست × "+ex.get(i)[3]+" تکرار");}}});new AlertDialog.Builder(this).setTitle("ثبت تمرین").setView(l).setPositiveButton("ثبت",(d,w)->{try{int i=ps.getSelectedItemPosition(),j=es.getSelectedItemPosition();List<String[]> ex=db.exercises(Long.parseLong(p.get(i)[0]));if(j<0||j>=ex.size())throw new Exception();String[] e=ex.get(j);db.log(date[0],p.get(i)[1],e[1],Integer.parseInt(e[2]),Integer.parseInt(e[3]),Double.parseDouble(kg.getText().toString()));status.setText("آخرین ثبت: "+date[0]);msg("ثبت شد","تمرین ذخیره شد");}catch(Exception x){msg("خطا","حرکت و وزن معتبر وارد کنید");}}).setNegativeButton("لغو",null).show();}
 void steps(){if(step==null){msg("ناموجود","حسگر قدم‌شمار در این گوشی موجود نیست.");return;}if(android.os.Build.VERSION.SDK_INT>=29&&checkSelfPermission("android.permission.ACTIVITY_RECOGNITION")!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{"android.permission.ACTIVITY_RECOGNITION"},21);return;}startSteps();}void startSteps(){try{Intent i=new Intent(this,StepCounterService.class);if(android.os.Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);status.setText("قدم‌شمار در پس‌زمینه فعال است");msg("قدم‌شمار فعال شد","شمارش قدم‌ها با خاموش شدن صفحه هم ادامه می‌یابد. اعلان قدم‌شمار را برای وضعیت فعال نگه دارید.");}catch(Exception e){msg("خطا","فعال‌سازی قدم‌شمار انجام نشد. مجوز فعالیت بدنی را بررسی کنید.");}}public void onRequestPermissionsResult(int requestCode,String[] permissions,int[] grantResults){super.onRequestPermissionsResult(requestCode,permissions,grantResults);if(requestCode==21&&grantResults.length>0&&grantResults[0]==android.content.pm.PackageManager.PERMISSION_GRANTED)startSteps();else if(requestCode==21)msg("مجوز لازم است","برای شمارش قدم‌ها باید مجوز فعالیت بدنی داده شود.");}public void onSensorChanged(SensorEvent e){}public void onAccuracyChanged(Sensor s,int a){}protected void onPause(){super.onPause();}

 void report(){
  LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(24,12,24,8);
  TextView intro=new TextView(this);intro.setText("خلاصه تمرین‌ها، حجم وزنه و روند فعالیت");intro.setTextColor(0xFF53617A);intro.setTextSize(14);root.addView(intro);
  Spinner range=new Spinner(this);String[] choices={"۷ روز اخیر","۳۰ روز اخیر","همه سوابق"};range.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,choices));LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,-2);rp.topMargin=12;root.addView(range,rp);
  TextView stats=new TextView(this);stats.setTextColor(0xFF17233D);stats.setTextSize(16);stats.setPadding(0,18,0,18);root.addView(stats);
  ReportChartView chart=new ReportChartView(this);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,230);root.addView(chart,cp);
  TextView detail=new TextView(this);detail.setTextColor(0xFF53617A);detail.setTextSize(13);detail.setPadding(0,14,0,8);root.addView(detail);
  Runnable refresh=()->{
   int days=range.getSelectedItemPosition()==0?7:range.getSelectedItemPosition()==1?30:0;
   long now=System.currentTimeMillis(), cutoff=days==0?0:now-days*86400000L;
   int workouts=0,totalSets=0,totalReps=0;double volume=0;TreeMap<String,Integer> counts=new TreeMap<>();TreeMap<String,Double> volumes=new TreeMap<>();
   try(android.database.Cursor cur=db.reportLogs()){while(cur.moveToNext()){long ts=cur.getLong(6);if(ts<cutoff)continue;workouts++;String date=cur.getString(0);int sets=cur.getInt(3),reps=cur.getInt(4);double kg=cur.getDouble(5);totalSets+=sets;totalReps+=sets*reps;volume+=sets*reps*kg;counts.put(date,counts.containsKey(date)?counts.get(date)+1:1);volumes.put(date,(volumes.containsKey(date)?volumes.get(date):0)+sets*reps*kg);}}
   stats.setText("جلسه‌های ثبت‌شده: "+workouts+"\nمجموع ست‌ها: "+totalSets+"   •   تکرارها: "+totalReps+"\nحجم تمرین وزنه‌ای: "+String.format(java.util.Locale.US,"%.1f",volume)+" کیلوگرم×تکرار");
   ArrayList<String> labels=new ArrayList<>();ArrayList<Float> vals=new ArrayList<>();
   if(days>0){for(int i=days-1;i>=0;i--){java.text.SimpleDateFormat fmt=new java.text.SimpleDateFormat("yyyy-MM-dd",java.util.Locale.US);String key=fmt.format(new java.util.Date(now-i*86400000L));String jalali=JalaliDate.fromGregorian(Integer.parseInt(key.substring(0,4)),Integer.parseInt(key.substring(5,7)),Integer.parseInt(key.substring(8,10)));labels.add(jalali.length()>=5?jalali.substring(jalali.length()-5):jalali);vals.add((float)(counts.containsKey(jalali)?counts.get(jalali):0));}}
   else {for(String key:counts.keySet()){labels.add(key.length()>=5?key.substring(key.length()-5):key);vals.add((float)counts.get(key));}}
   chart.setData(labels,vals);
   if(workouts==0)detail.setText("برای این بازه هنوز تمرینی ثبت نشده است.");else detail.setText("نمودار تعداد ثبت تمرین در هر روز را نشان می‌دهد. حجم وزنه بر اساس ست × تکرار × وزن واردشده محاسبه شده است.");
  };
  range.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> a){}public void onItemSelected(AdapterView<?> a,View v,int p,long id){refresh.run();}});
  refresh.run();
  ScrollView scroll=new ScrollView(this);scroll.addView(root);
  new AlertDialog.Builder(this).setTitle("گزارش عملکرد").setView(scroll).setPositiveButton("بستن",null).setNeutralButton("خروجی سوابق", (d,w)->export()).show();
 }

 void export(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("text/csv");i.putExtra(Intent.EXTRA_TITLE,"fit-yar-workouts.csv");startActivityForResult(i,EXPORT);}protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==EXPORT&&c==RESULT_OK&&d!=null)try(OutputStream o=getContentResolver().openOutputStream(d.getData());Cursor cur=db.allLogs()){if(o==null)throw new IOException("Unable to open export destination");o.write("date,plan,exercise,sets,reps,weight\n".getBytes(StandardCharsets.UTF_8));while(cur.moveToNext()){StringBuilder b=new StringBuilder();for(int j=0;j<6;j++){if(j>0)b.append(',');String cell=cur.getString(j);if(cell==null)cell="";b.append('"').append(cell.replace("\"","\"\"")).append('"');}o.write((b+"\n").getBytes(StandardCharsets.UTF_8));}msg("انجام شد","فایل ذخیره شد");}catch(Exception e){msg("خطا","ساخت فایل انجام نشد");}}
}
